#!/usr/bin/env bash\nset -euo pipefail\n\n# Build the Docker image\nIMAGE_NAME="nightly-docker-whimsy-quote-test"\ndocker build -t "$IMAGE_NAME" . > /dev/null\n\n# Determine the expected quote (second line)\nEXPECTED=$(sed -n '2p' src/quotes.txt)\n\n# Run the container with QUOTE_INDEX=2 to get deterministic output\nOUTPUT=$(docker run --rm -e QUOTE_INDEX=2 "$IMAGE_NAME")\n\nif [ "$OUTPUT" = "$EXPECTED" ]; then\n  echo "PASS: deterministic quote matches expected output"\n  exit 0\nelse\n  echo "FAIL: expected '$EXPECTED' but got '$OUTPUT'"\n  exit 1\nfi
